function ReportBars({items}){const vals=items.filter(x=>Number.isFinite(x.value));if(!vals.length)return <Empty text="لا توجد نتائج كافية للرسم البياني"/>;const max=Math.max(1,...vals.map(x=>x.value));return <div className="report-bars">{vals.map((x,i)=><div className="report-bar-row" key={x.label+i}><span title={x.label}>{x.label}</span><div><i style={{width:`${Math.max(2,x.value/max*100)}%`}}/></div><b>{x.display??x.value}</b></div>)}</div>}
function ReportLine({points,label,unit=''}){const vals=points.filter(x=>Number.isFinite(x.value));if(!vals.length)return <Empty text="لا توجد قياسات كافية للرسم البياني"/>;const min=Math.min(...vals.map(x=>x.value)),max=Math.max(...vals.map(x=>x.value)),range=max-min||1;const coords=vals.map((x,i)=>({x:24+(vals.length===1?0:i*252/(vals.length-1)),y:104-(x.value-min)/range*76,...x}));return <div className="report-line-wrap"><b>{label}</b><svg viewBox="0 0 300 130" role="img" aria-label={label}><line x1="20" y1="104" x2="280" y2="104" stroke="#dce8df"/><polyline fill="none" stroke="#268653" strokeWidth="3" strokeLinecap="round" strokeLinejoin="round" points={coords.map(c=>`${c.x},${c.y}`).join(' ')}/>{coords.map((c,i)=><g key={i}><circle cx={c.x} cy={c.y} r="4" fill="#268653"/><text x={c.x} y={Math.max(12,c.y-9)} textAnchor="middle" fontSize="9" fill="#385c48">{c.value.toFixed(2)}</text></g>)}</svg><div className="report-line-labels"><span>{vals[0].date}</span><span>{vals.at(-1).date}</span></div><small>الوحدة: {unit||'حسب الاختبار'} · عدد القياسات: {vals.length}</small></div>}

