 async function auth(){setBusy(true);try{if(signup){const{error}=await supabase.auth.signUp({email:email.trim(),password,options:{data:{full_name:fullName.trim()}}});if(error)throw error;notify('تم إنشاء الحساب. ينتظر موافقة الإدارة بعد تأكيد البريد إذا كان مطلوبًا.');setSignup(false)}else{const{error}=await supabase.auth.signInWithPassword({email:email.trim(),password});if(error)throw error}}catch(e){notify(msg(e))}finally{setBusy(false)}}
 async function signout(){await supabase.auth.signOut();setSession(null);setProfile(null)}
 async function insert(table,row,success,refresh=true){if(!navigator.onLine){if(OFFLINE_OK.includes(table)){qSet([...qGet(),{table,row}]);notify('تم الحفظ على الجهاز دون إنترنت، وسيُرسل عند عودة الاتصال');return true}notify('هذه العملية تحتاج إنترنت');return false}if(viewingArchived){notify('هذه سنة مؤرشفة (قراءة فقط)');return false}setBusy(true);try{const{error}=await supabase.from(table).insert(row);if(error)throw error;notify(success);if(refresh)await loadAll();return true}catch(e){notify(msg(e));return false}finally{setBusy(false)}}
 async function addStudent(){if(!newStudent.student_number||!newStudent.full_name.trim())return notify('أدخل رقم التلميذ واسمه');await insert('students',{student_number:Number(newStudent.student_number),full_name:newStudent.full_name.trim(),gender:newStudent.gender||null,birth_date:newStudent.birth_date||null},'تمت إضافة التلميذ');setNewStudent({student_number:'',full_name:'',gender:'',birth_date:''})}
 async function markAttendance(student,status,reason=null){if(viewingArchived)return notify('هذه سنة مؤرشفة (قراءة فقط)');const activeSession=sessions.find(x=>x.coach_id===profile.id&&!x.end_time&&x.session_date===today());const row={institution_id:profile.institution_id,student_id:student.id,session_id:activeSession?.id||null,attendance_date:date,status,recorded_by:profile.id,absence_reason:status==='absent'?(reason||'ordinary'):null};const old=attendanceAll.find(x=>x.student_id===student.id&&x.attendance_date===date&&(x.session_id||null)===(activeSession?.id||null));setBusy(true);try{const q=old?supabase.from('attendance').update(row).eq('id',old.id).select().single():supabase.from('attendance').insert(row).select().single();const{data,error}=await q;if(error)throw error;setAttendance(a=>old?a.map(x=>x.id===old.id?data:x):[data,...a]);notify('تم تسجيل الحالة')}catch(e){notify(msg(e))}finally{setBusy(false)}}
 async function saveNote(){if(!note.trim())return;await insert('coach_notebook',{owner_id:profile.id,body:note.trim()},'حُفظت الملاحظة في كراسك الخاص');setNote('')}
