 async function addCoreTests(){
  const defaults=[{name:'Navette 20 m (Léger)',unit:'palier',higher_is_better:true},{name:'Pompes',unit:'تكرار',higher_is_better:true},{name:'Abdos',unit:'تكرار',higher_is_better:true}]
  const existing=new Set(tests.map(t=>(t.name||'').trim().toLowerCase()))
  const missing=defaults.filter(t=>!existing.has(t.name.toLowerCase()))
  if(!missing.length)return notify('الاختبارات الثلاثة موجودة بالفعل')
  setBusy(true);try{const{error}=await supabase.from('test_definitions').insert(missing.map(t=>({institution_id:profile.institution_id,...t})));if(error)throw error;notify(`تمت إضافة ${missing.length} اختبار/اختبارات`);await loadAll()}catch(e){notify('تعذّرت إضافة الاختبارات: '+msg(e))}finally{setBusy(false)}
 }
