 async function addTest(){if(!testForm.name.trim())return notify('اكتب اسم الاختبار');await insert('test_definitions',{institution_id:profile.institution_id,...testForm,name:testForm.name.trim()},'تمت إضافة الاختبار');setTestForm({name:'',unit:'',higher_is_better:true})}
 async function saveScale(){if(!scaleTest||!scale.trim())return notify('اختر الاختبار وأدخل جدول التنقيط');let rules;try{rules=JSON.parse(scale);if(!Array.isArray(rules))throw new Error('JSON must be array')}catch{rules=scale.trim().split(/\r?\n/).map(line=>line.trim()).filter(Boolean).map(line=>line.split(/[\t,;|]+/).map(x=>x.trim())).filter(cols=>cols.length>=2&&Number.isFinite(Number(cols[0]))&&Number.isFinite(Number(cols[1]))).map(cols=>({rawValue:Number(cols[0]),score:Number(cols[1])}));if(!rules.length)return notify('تعذّر قراءة الجدول. الصق عمود النتيجة الخام ثم الدرجة، مفصولين بعلامة Tab أو فاصلة.')}if(rules.some(x=>!Number.isFinite(Number(x.rawValue))||!Number.isFinite(Number(x.score))))return notify('توجد قيم غير رقمية في BARÈME');const{data:vers,error:ve}=await supabase.from('scale_versions').select('version').eq('test_id',scaleTest).order('version',{ascending:false}).limit(1);if(ve)return notify(msg(ve));const version=(vers?.[0]?.version||0)+1;await insert('scale_versions',{institution_id:profile.institution_id,test_id:scaleTest,version,valid_from:today(),rules},`تم حفظ إصدار BARÈME رقم ${version}`);}
 async function saveResult(){if(viewingArchived)return notify('هذه سنة مؤرشفة (قراءة فقط)');if(!resultForm.student_id||!resultForm.test_id||resultForm.raw_value==='')return notify('أكمل بيانات النتيجة');const raw=Number(resultForm.raw_value);if(!Number.isFinite(raw))return notify('النتيجة يجب أن تكون رقمًا');if((isNavette&&(!Number.isInteger(raw)||raw<1))||(isRepTest&&(!Number.isInteger(raw)||raw<0)))return notify(isNavette?'أدخل رقم palier صحيحاً يبدأ من 1':'أدخل عدداً صحيحاً للتكرارات');const{data:sv,error}=await supabase.from('scale_versions').select('*').eq('test_id',resultForm.test_id).lte('valid_from',resultForm.tested_on).order('version',{ascending:false}).limit(1);if(error)return notify(msg(error));let score=null,scale_version_id=null;if(sv?.length){scale_version_id=sv[0].id;const rules=Array.isArray(sv[0].rules)?sv[0].rules:[];const matches=rules.filter(x=>Number.isFinite(Number(x.rawValue))&&Number(x.rawValue)>=raw);if(matches.length){matches.sort((a,b)=>Number(a.rawValue)-Number(b.rawValue));score=Number(matches[0].score)}}const{error:er}=await supabase.from('test_results').insert({institution_id:profile.institution_id,student_id:resultForm.student_id,test_id:resultForm.test_id,raw_value:raw,score,scale_version_id,tested_on:resultForm.tested_on,recorded_by:profile.id});if(er)notify(msg(er));else{notify(score===null?'حُفظت النتيجة الخام؛ لا يوجد تطابق في BARÈME.':'تم حفظ النتيجة والدرجة');setResultForm({...resultForm,raw_value:''});loadAll()}}
 function openSession(s){if(!s)return;setSelectedSession(s);setSessionNoteDraft(s.notes||'');setSessionAbsText('');setSessionAbsPreview(null);setPage('sessions')}
 async function startSession(){
  if(viewingArchived)return notify('السنة المعروضة مؤرشفة؛ اختر السنة الحالية');
  if(!profile?.id||!profile?.institution_id)return notify('تعذّر تحديد حساب المدرب أو المؤسسة');
  if(!navigator.onLine)return notify('إنشاء الحصة يحتاج اتصالاً بالإنترنت');
  setBusy(true);
  try{
   const{data:existing,error:findError}=await supabase.from('sessions').select('*').eq('institution_id',profile.institution_id).eq('coach_id',profile.id).is('end_time',null).order('created_at',{ascending:false}).limit(1).maybeSingle();
   if(findError)throw findError;
   if(existing){setSessions(a=>[existing,...a.filter(x=>x.id!==existing.id)]);openSession(existing);notify('لديك حصة لم تُنهَ بعد. فتحناها لمواصلة العمل.');return}
   const{data,error}=await supabase.from('sessions').insert({institution_id:profile.institution_id,coach_id:profile.id,session_date:today(),start_time:new Date().toTimeString().slice(0,8),notes:''}).select('*').single();
   if(error)throw error;setSessions(a=>[data,...a.filter(x=>x.id!==data.id)]);openSession(data);notify('بدأت الحصة. سجّل الغائبين داخلها.');
  }catch(e){notify('تعذّر إنشاء أو فتح الحصة: '+msg(e))}finally{setBusy(false)}
 }
 async function endSession(s){if(!s||s.coach_id!==profile.id)return notify('لا يمكنك إنهاء حصة مدرب آخر');if(s.end_time)return notify('هذه الحصة منتهية بالفعل');if(!window.confirm('هل تريد إنهاء الحصة وحفظ وقت النهاية؟'))return;setBusy(true);try{const end_time=new Date().toTimeString().slice(0,8);const{data,error}=await supabase.from('sessions').update({end_time}).eq('id',s.id).eq('coach_id',profile.id).is('end_time',null).select('*').single();if(error)throw error;setSessions(a=>a.map(x=>x.id===s.id?data:x));setSelectedSession(data);notify('تم إنهاء الحصة وحفظ وقت النهاية والمدة')}catch(e){notify('تعذّر إنهاء الحصة: '+msg(e))}finally{setBusy(false)}}
 function sessionDraftMatches(){const reasonMap=[['رخصة','permission'],['إعفاء','exempt'],['اعفاء','exempt'],['واجب','official_duty'],['عادي','ordinary'],['عادية','ordinary']];return sessionAbsText.split(/[\n,;،؛]+/).map(x=>x.trim()).filter(Boolean).map(line=>{const m=line.match(/^(\d+)\s*(.*)$/);if(!m)return{line,student:null,reason:null};const matches=students.filter(x=>Number(x.student_number)===Number(m[1]));const found=reasonMap.find(([word])=>m[2].includes(word));return{line,student:matches.length===1?matches[0]:null,reason:found?.[1]||'ordinary',invalid:matches.length!==1}})}
 function previewSessionAbsences(){const rows=[],bad=[],seen=new Set();const reasonMap=[['رخصة','permission'],['إعفاء','exempt'],['اعفاء','exempt'],['واجب','official_duty'],['عادي','ordinary'],['عادية','ordinary']];for(const line of sessionAbsText.split(/[\n,;،؛]+/).map(x=>x.trim()).filter(Boolean)){const m=line.match(/^(\d+)\s*(.*)$/);if(!m){bad.push(line+' (صيغة غير مفهومة)');continue}const num=Number(m[1]),matches=students.filter(x=>Number(x.student_number)===num);if(matches.length!==1){bad.push(`${num} (${matches.length?'رقم مكرر':'رقم غير موجود'})`);continue}if(seen.has(num)){bad.push(`${num} (مكرر)`);continue}seen.add(num);const tail=m[2].trim();const found=reasonMap.find(([word])=>tail.includes(word));rows.push({student:matches[0],reason:found?.[1]||'ordinary'})}setSessionAbsPreview({rows,bad})}
 async function saveSessionAttendance(s){if(!s||s.end_time)return notify('الحصة منتهية ولا يمكن تعديل حضورها');if(viewingArchived)return notify('السنة مؤرشفة؛ لا يمكن التعديل');if(!sessionAbsPreview)return notify('عاين قائمة الغيابات أولاً');if(sessionAbsPreview.bad.length)return notify('صحّح الأرقام غير المقبولة قبل الحفظ');if(!students.length)return notify('لا توجد قائمة تلاميذ بالمؤسسة');const absent=new Map(sessionAbsPreview.rows.map(x=>[x.student.id,x]));const payload=students.map(st=>({institution_id:profile.institution_id,student_id:st.id,session_id:s.id,attendance_date:s.session_date,status:absent.has(st.id)?'absent':'present',recorded_by:profile.id,absence_reason:absent.has(st.id)?absent.get(st.id).reason:null}));setBusy(true);try{const{data,error}=await supabase.from('attendance').upsert(payload,{onConflict:'student_id,attendance_date,session_id'}).select();if(error)throw error;setAttendance(a=>[...a.filter(x=>x.session_id!==s.id),...(data||[])]);setSessionAbsText('');setSessionAbsPreview(null);notify(`تم حفظ الحصة: ${absent.size} غائب و${students.length-absent.size} حاضر تلقائياً`);await loadAll()}catch(e){notify('لم يتم حفظ الحضور: '+msg(e))}finally{setBusy(false)}}
 async function saveSessionNotes(s){if(!s||s.coach_id!==profile.id||s.end_time)return notify('لا يمكن تعديل ملاحظات هذه الحصة');const{data,error}=await supabase.from('sessions').update({notes:sessionNoteDraft.trim()}).eq('id',s.id).eq('coach_id',profile.id).select().single();if(error){notify('تعذّر حفظ ملاحظات الحصة: '+msg(error));return}setSessions(a=>a.map(x=>x.id===s.id?data:x));setSelectedSession(data);notify('تم حفظ ملاحظات الحصة')}

 async function updateMember(member,patch){const{error}=await supabase.from('profiles').update(patch).eq('id',member.id);if(error)notify(msg(error));else{notify('تم تحديث الحساب');loadAll()}}
